-- RC-EVO Ciclo 2 Sprint 3 (educacao/biblioteca circulacao completa) — idempotente; multi-esfera (regra 24).
-- BR-3.1 a BR-3.8: prazo original/renovacoes no emprestimo, origem FNLI no acervo, inventario fisico
-- (snapshot + contagem idempotente + divergencia justificada), devolucao unica por emprestimo (backstop
-- transacional da idempotencia), CONSUMIDA como estado terminal da reserva e parametros de circulacao
-- no catalogo global do modulo EDUCACAO (tenant sobrescreve via salvar_parametro_modulo; regra 11).
-- Falha de schema ausente fica explicita na pos-condicao C2S3-POSTCOND (regra 13).

-- 1) Colunas de renovacao (BR-3.3) e origem FNLI (BR-3.8)
alter table sigov.educacao_biblioteca_emprestimo add column if not exists prazo_original date;
alter table sigov.educacao_biblioteca_emprestimo add column if not exists renovacoes integer not null default 0;
update sigov.educacao_biblioteca_emprestimo set prazo_original = data_fim where prazo_original is null;
alter table sigov.educacao_biblioteca_acervo add column if not exists origem varchar(40);

-- 2) Inventario fisico (BR-3.5): cabecalho do snapshot + itens por exemplar
create table if not exists sigov.educacao_biblioteca_inventario (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint, escola_id bigint, codigo varchar(120), numero bigint, nome varchar(240), tipo varchar(80), categoria varchar(120), status varchar(40) not null default 'ABERTO', descricao text, justificativa text, quantidade numeric(18,4), valor numeric(18,2), competencia date, data_inicio date, data_fim date, prazo_at timestamptz, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb, correlation_id uuid not null default gen_random_uuid(), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create index if not exists ix_educacao_biblioteca_inventario_tenant_status on sigov.educacao_biblioteca_inventario(tenant_id,status) where is_deleted=false and ativo=true;

create table if not exists sigov.educacao_biblioteca_inventario_item (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint, escola_id bigint, referencia_id bigint, exemplar_id bigint, codigo varchar(120), nome varchar(240), tipo varchar(80), status varchar(40) not null default 'ABERTA', descricao text, justificativa text, quantidade numeric(18,4), posicao_status varchar(40), status_contado varchar(40), desfecho varchar(40), dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb, correlation_id uuid not null default gen_random_uuid(), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
-- uma contagem por exemplar x inventario: reenvio da contagem tem efeito unico (upsert sobre o backstop)
create unique index if not exists ux_biblioteca_inventario_item_tenant_inv_exemplar on sigov.educacao_biblioteca_inventario_item(tenant_id, coalesce(referencia_id,0), coalesce(exemplar_id,0)) where is_deleted=false;

-- 3) Devolucao unica por emprestimo (BR-3.2): idempotencia com backstop transacional.
-- Dedupe legado preservando min(id) antes de criar o indice unico (mesmo padrao do dedupe de estoque do C2S1).
delete from sigov.educacao_biblioteca_devolucao d using sigov.educacao_biblioteca_devolucao k
 where k.tenant_id = d.tenant_id and k.referencia_id is not distinct from d.referencia_id
   and d.tipo = 'DEVOLUCAO' and k.tipo = 'DEVOLUCAO'
   and d.is_deleted = false and k.is_deleted = false and k.id < d.id;
create unique index if not exists ux_biblioteca_devolucao_tenant_emprestimo on sigov.educacao_biblioteca_devolucao(tenant_id, coalesce(referencia_id,0)) where is_deleted=false and tipo='DEVOLUCAO';

-- 4) CONSUMIDA entra nos estados terminais da vigência da reserva (BR-3.2: reserva consumida pela
-- devolucao libera a fila do exemplar e é irreversivel; recriacao idempotente do indice)
drop index if exists sigov.ux_biblioteca_reserva_tenant_exemplar_vigencia;
create unique index ux_biblioteca_reserva_tenant_exemplar_vigencia on sigov.educacao_biblioteca_reserva(tenant_id, coalesce(exemplar_id,0)) where is_deleted=false and ativo=true and status <> all (array['ENCERRADA','ENCERRADO','CANCELADA','CANCELADO','CONSUMIDA']);

-- 5) Parametros de circulacao (BR-3.1/BR-3.3): catalogo global do modulo EDUCACAO; o tenant pode
-- sobrescrever via salvar_parametro_modulo (parametro_modulo_valor) — banco como autoridade (regra 11)
insert into sigov.parametro_modulo(modulo,codigo,nome,descricao,tipo,valor_padrao,sensivel,ordem,ativo)
values
 ('EDUCACAO','EMPRESTIMO_MAX_VIGENTES_TOMADOR','Maximo de emprestimos vigentes por tomador','BR-3.1: limite de emprestimos vigentes por tomador (aluno/servidor) do tenant','INTEGER','2',false,130,true),
 ('EDUCACAO','EMPRESTIMO_PRAZO_PADRAO_DIAS','Prazo padrao de emprestimo em dias','BR-3.2: prazo aplicado ao emprestimo automatico oriundo de reserva consumida na devolucao','INTEGER','14',false,140,true),
 ('EDUCACAO','RENOVACAO_MAX_POR_EMPRESTIMO','Maximo de renovacoes por emprestimo','BR-3.3: limite de renovacoes por emprestimo','INTEGER','1',false,150,true),
 ('EDUCACAO','RENOVACAO_DIAS_ESTENDIMENTO','Dias de extensao por renovacao a partir do prazo original','BR-3.3: a renovacao estende a partir da data original (+ N dias por renovacao), nao da data atual','INTEGER','14',false,160,true)
on conflict do nothing;

-- C2S3-POSTCOND: falha explicita se faltar qualquer artefato do incremento (regra 13)
do $$
begin
  if not exists(select 1 from information_schema.columns where table_schema='sigov' and table_name='educacao_biblioteca_inventario' and column_name='status') then
    raise exception 'C2S3-POSTCOND: tabela sigov.educacao_biblioteca_inventario ausente';
  end if;
  if not exists(select 1 from information_schema.columns where table_schema='sigov' and table_name='educacao_biblioteca_inventario_item' and column_name='posicao_status') then
    raise exception 'C2S3-POSTCOND: coluna sigov.educacao_biblioteca_inventario_item.posicao_status ausente';
  end if;
  if not exists(select 1 from information_schema.columns where table_schema='sigov' and table_name='educacao_biblioteca_emprestimo' and column_name='prazo_original') then
    raise exception 'C2S3-POSTCOND: coluna sigov.educacao_biblioteca_emprestimo.prazo_original ausente';
  end if;
  if not exists(select 1 from information_schema.columns where table_schema='sigov' and table_name='educacao_biblioteca_acervo' and column_name='origem') then
    raise exception 'C2S3-POSTCOND: coluna sigov.educacao_biblioteca_acervo.origem ausente';
  end if;
  if not exists(select 1 from pg_indexes where schemaname='sigov' and indexname='ux_biblioteca_inventario_item_tenant_inv_exemplar') then
    raise exception 'C2S3-POSTCOND: indice ux_biblioteca_inventario_item_tenant_inv_exemplar ausente';
  end if;
  if not exists(select 1 from pg_indexes where schemaname='sigov' and indexname='ux_biblioteca_devolucao_tenant_emprestimo') then
    raise exception 'C2S3-POSTCOND: indice ux_biblioteca_devolucao_tenant_emprestimo ausente';
  end if;
  if (select count(1) from sigov.parametro_modulo where modulo='EDUCACAO' and codigo in ('EMPRESTIMO_MAX_VIGENTES_TOMADOR','EMPRESTIMO_PRAZO_PADRAO_DIAS','RENOVACAO_MAX_POR_EMPRESTIMO','RENOVACAO_DIAS_ESTENDIMENTO') and ativo and not is_deleted) <> 4 then
    raise exception 'C2S3-POSTCOND: parametros de circulacao incompletos no catalogo do modulo EDUCACAO';
  end if;
end$$;
